type ValueKey = 'clerkLimit' | 'floor' | 'terms' | 'latePct' | 'policyDate' | 'periodNumberingFrom' | 'termsA' | 'termsB' | 'termsC' | 'cap' | 'proofThreshold' | 'graceDays' | 'noteThreshold' | 'entryDate' | 'graceA' | 'graceB' | 'graceC' | 'proofThresholdA' | 'proofThresholdB' | 'proofThresholdC' | 'pot' | 'parent' | 'fiscalStartMonth' | 'alertThreshold' | 'rounding' | 'reviewThreshold' | 'escalateAfter' | 'reviewSla' | 'proofKinds' | 'defaultGrade' | 'clerkLimitA' | 'clerkLimitB' | 'clerkLimitC' | 'scoreMid' | 'scoreHigh' | 'scoreLog' | 'maxOpen' | 'pendingSla' | PermKey;

/** The permission matrix: for each action, the roles that may take it (comma separated; blank: the standing rule).
 *  Not dated. */
const PERMS = [
  { action: 'open', key: 'permOpen', standing: 'clerk,steward' },
  { action: 'settle', key: 'permSettle', standing: 'clerk,steward' },
  { action: 'void', key: 'permVoid', standing: 'clerk,steward' },
  { action: 'reassign', key: 'permReassign', standing: 'steward' },
  { action: 'close', key: 'permClose', standing: 'clerk,steward' },
  { action: 'reopen', key: 'permReopen', standing: 'steward' },
  { action: 'today', key: 'permToday', standing: 'anyone but a viewer' },
] as const;
type PermKey = (typeof PERMS)[number]['key'];

/** The settings that carry a figure: each is saved from a from-date (blank: the sheet's today). */
const DATED = ['clerkLimit', 'clerkLimitA', 'clerkLimitB', 'clerkLimitC', 'floor', 'terms', 'latePct', 'termsA', 'termsB', 'termsC', 'cap', 'proofThreshold', 'noteThreshold', 'graceA', 'graceB', 'graceC', 'proofThresholdA', 'proofThresholdB', 'proofThresholdC', 'rounding', 'reviewThreshold'] as const;
type DatedKey = (typeof DATED)[number];
